/* fuzz_tok_encode - third_party/tok.h + src/tokenizer/k3_tok.h: the prompt path of
 * `k3 --prompt/--prompt-file`. UTF-8 decoding, the kimi/o200k pre-tokenizer, rank BPE,
 * added-token matching, then decode of the ids.
 *
 * The vocabulary is the repository's tests/fixtures/tok/good, compiled into the
 * harness (k3_embed_tok.h, generated by build.sh) and loaded once into the scratch
 * directory; it is read-only after load. The whole input is the prompt text.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "k3_fuzz_util.h"
#include "k3_tok.h"
#include "k3_embed_tok.h"

static Tok T;
static int loaded;

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    if (!loaded) {
        fz_write("tiktoken.model", k3e_good_tiktoken, sizeof k3e_good_tiktoken);
        fz_write("tokenizer_config.json", k3e_good_tokcfg, sizeof k3e_good_tokcfg);
        k3_tok_load(&T, fz_dir());
        loaded = 1;
    }
    if (size > (1 << 20)) return -1;
    const int max = (int)size + 1;
    int *ids = (int *)malloc((size_t)max * sizeof(int));
    char *back = (char *)malloc((size_t)size * 8 + 64);
    if (!ids || !back) { free(ids); free(back); return 0; }

    /* With added tokens recognised (tok_encode, the CLI prompt), and as plain text
     * (tok_encode_mode allow_added=0, what chat rendering uses for user content). */
    int n = tok_encode(&T, (const char *)data, (int)size, ids, max);
    (void)tok_decode(&T, ids, n, back, (int)size * 8 + 63);
    n = tok_encode_mode(&T, (const char *)data, (int)size, ids, max, 0);
    (void)tok_decode(&T, ids, n, back, (int)size * 8 + 63);

    /* The input read as raw ids too (decode skips ids it has no string for). */
    int nid = (int)(size / 4);
    if (nid > 0) {
        int *raw = (int *)malloc((size_t)nid * sizeof(int));
        if (raw) {
            memcpy(raw, data, (size_t)nid * sizeof(int));
            (void)tok_decode(&T, raw, nid, back, (int)size * 8 + 63);
            free(raw);
        }
    }
    free(ids);
    free(back);
    return 0;
}
